using RestaurantSystem.Domain.Catalog;

namespace RestaurantSystem.Domain.Operations;

public sealed class ProductComposition { public Guid Id { get; set; } = Guid.NewGuid(); public Guid ParentProductId { get; set; } public Guid ComponentProductId { get; set; } public decimal QuantityPerOutputUnit { get; set; } public Guid UnitId { get; set; } public DateTimeOffset CreatedAt { get; set; } public required string CreatedByUserId { get; set; } }
public enum ProductionStatus { COMPLETED }
public sealed class Production { public Guid Id { get; set; } = Guid.NewGuid(); public required string BatchCode { get; set; } public ProductionStatus Status { get; set; } = ProductionStatus.COMPLETED; public Guid ProductId { get; set; } public decimal QuantityProduced { get; set; } public Guid? ResponsibleEmployeeId { get; set; } public string? Notes { get; set; } public DateTimeOffset ProducedAt { get; set; } public required string CreatedByUserId { get; set; } public List<ProductionConsumption> Consumptions { get; set; } = []; }
