public enum ShiftType { MORNING, NIGHT }
public enum ShiftStatus { PENDING, ACTIVE, COMPLETED }
public sealed class CashSession { public Guid Id { get; set; } = Guid.NewGuid(); public DateOnly BusinessDate { get; set; } public bool IsOpen { get; set; } = true; public DateTimeOffset OpenedAt { get; set; } public required string OpenedByUserId { get; set; } public decimal? OpeningAmount { get; set; } public decimal? PettyCashOpeningAmount { get; set; } public decimal? CashRemovedAmount { get; set; } public decimal? CashAmountCarriedForward { get; set; } public List<Shift> Shifts { get; set; } = []; }
public sealed class CashClosing { public Guid Id { get; set; } = Guid.NewGuid(); public Guid CashSessionId { get; set; } public DateOnly BusinessDate { get; set; } public decimal OpeningAmount { get; set; } public decimal PettyCashOpeningAmount { get; set; } public decimal CashRemovedAmount { get; set; } public decimal SalesTotal { get; set; } public decimal CashSalesTotal { get; set; } public decimal QrSalesTotal { get; set; } public decimal ExternalSalesTotal { get; set; } public decimal DirectSalesTotal { get; set; } public decimal PedidosYaSalesTotal { get; set; } public decimal CashDrawerExpensesTotal { get; set; } public decimal PettyCashExpensesTotal { get; set; } public decimal ExpensesTotal { get; set; } public decimal ExpectedCash { get; set; } public decimal DeclaredCash { get; set; } public decimal Difference { get; set; } public string? Observation { get; set; } public required string ClosedByUserId { get; set; } public DateTimeOffset ClosedAt { get; set; } }
public sealed class Shift { public Guid Id { get; set; } = Guid.NewGuid(); public Guid CashSessionId { get; set; } public ShiftType Type { get; set; } public ShiftStatus Status { get; set; } = ShiftStatus.PENDING; public DateTimeOffset? StartedAt { get; set; } public DateTimeOffset? EndedAt { get; set; } public string? HandoverNote { get; set; } public List<ShiftAssignment> Assignments { get; set; } = []; }
public sealed class WorkSchedule { public Guid Id { get; set; } = Guid.NewGuid(); public ShiftType ShiftType { get; set; } public TimeOnly PlannedStart { get; set; } public TimeOnly PlannedEnd { get; set; } public int LateToleranceMinutes { get; set; } }
public sealed class ShiftAssignment { public Guid Id { get; set; } = Guid.NewGuid(); public Guid ShiftId { get; set; } public Guid EmployeeId { get; set; } public DateTimeOffset AssignedAt { get; set; } public required string AssignedByUserId { get; set; } public TimeOnly EffectivePlannedStart { get; set; } public TimeOnly EffectivePlannedEnd { get; set; } public int EffectiveLateToleranceMinutes { get; set; } }
public enum SalesChannel { DIRECT, PEDIDOSYA }
public enum PaymentMethod { CASH, QR, EXTERNAL }
public sealed class Sale { public Guid Id { get; set; } = Guid.NewGuid(); public Guid OrderId { get; set; } public Guid ShiftId { get; set; } public Guid? CustomerId { get; set; } public string? CustomerNameSnapshot { get; set; } public string? CustomerCiSnapshot { get; set; } public string? CustomerNitSnapshot { get; set; } public SalesChannel SalesChannel { get; set; } public PaymentMethod PaymentMethod { get; set; } public decimal Subtotal { get; set; } public decimal Total { get; set; } public DateTimeOffset ConfirmedAt { get; set; } public required string ConfirmedByUserId { get; set; } public List<SaleItem> Items { get; set; } = []; }
public sealed class SaleItem { public Guid Id { get; set; } = Guid.NewGuid(); public Guid SaleId { get; set; } public Guid OrderItemId { get; set; } public Guid ProductId { get; set; } public decimal Quantity { get; set; } public decimal UnitPrice { get; set; } public decimal LineTotal { get; set; } }
public enum PurchaseStatus { PENDIENTE, RECIBIDA, CANCELADA }
public sealed class Purchase { public Guid Id { get; set; } = Guid.NewGuid(); public Guid SupplierId { get; set; } public PurchaseStatus Status { get; set; } = PurchaseStatus.PENDIENTE; public DateOnly PurchaseDate { get; set; } public decimal Total { get; set; } public string? ReceiptReference { get; set; } public string? Notes { get; set; } public string? CancellationReason { get; set; } public DateTimeOffset? CancelledAt { get; set; } public string? CancelledByUserId { get; set; } public DateTimeOffset CreatedAt { get; set; } public required string CreatedByUserId { get; set; } public List<PurchaseItem> Items { get; set; } = []; }
